$ErrorActionPreference = 'SilentlyContinue'
# Outside a CodeAgentSwarm terminal (no quadrant env) stay silent.
if (-not $env:CODEAGENTSWARM_CURRENT_QUADRANT) { exit 0 }
$termId = $env:CODEAGENTSWARM_CURRENT_QUADRANT

# Async reads enforce a deadline even when the producer leaves stdin open.
$InputStream = [Console]::OpenStandardInput()
$InputBuffer = New-Object byte[] 65536
$InputBytes = New-Object IO.MemoryStream
$InputClock = [Diagnostics.Stopwatch]::StartNew()
try {
    while ($true) {
        $Remaining = 5000 - [int]$InputClock.ElapsedMilliseconds
        if ($Remaining -le 0) { exit 0 }
        $Read = $InputStream.ReadAsync($InputBuffer, 0, $InputBuffer.Length)
        if (-not $Read.Wait($Remaining)) { exit 0 }
        $Count = $Read.Result
        if ($Count -eq 0) { break }
        if ($InputBytes.Length + $Count -gt 1048576) { exit 0 }
        $InputBytes.Write($InputBuffer, 0, $Count)
    }
    $InputBytes.Position = 0
} catch { exit 0 }

try {
    $inputJson = [Text.Encoding]::UTF8.GetString($InputBytes.ToArray())
    $data = $inputJson | ConvertFrom-Json -ErrorAction Stop
} catch { exit 0 } finally { $InputBytes.Dispose() }


function Read-FileSnapshot([string]$FilePath) {
    $FileReader = [IO.File]::OpenText($FilePath)
    try {
        $FileSize = $FileReader.BaseStream.Length
        if ($FileSize -gt 1048576) { throw 'Snapshot too large' }
        $Chars = New-Object char[] ([int]$FileSize + 1)
        $Length = $FileReader.ReadBlock($Chars, 0, $Chars.Length)
        if ($Length -eq $Chars.Length -or $FileReader.BaseStream.Length -gt 1048576) { throw 'Snapshot grew during read' }
        # Native string: Get-Content adds provider metadata that PS 5.1 JSON expands.
        return [string]::new($Chars, 0, $Length)
    } finally { $FileReader.Dispose() }
}

$a = $data.toolCall.args
if (-not $a) { exit 0 }
$filePath = $a.TargetFile; if (-not $filePath) { $filePath = $a.AbsolutePath }
if (-not $filePath) { exit 0 }
$newContent = $a.CodeContent; if (-not $newContent) { $newContent = $a.Content }
$toolName = $data.toolCall.name; if (-not $toolName) { $toolName = 'write_to_file' }
$originalContent = ''
if (Test-Path -LiteralPath $filePath) { try { $originalContent = Read-FileSnapshot $filePath } catch { exit 0 } }
$body = @{ type='file_edited'; terminalId=$termId; toolName=$toolName; filePath=$filePath; content=$newContent; originalContent=$originalContent; newContent=$newContent } | ConvertTo-Json -Compress
# Post to THIS instance's webhook port when CodeAgentSwarm injected it; otherwise fall
# back to the legacy dev-first (45783) / prod (45782) probe for older builds.
$ports = if (($casPort = $env:CODEAGENTSWARM_WEBHOOK_PORT -as [int])) { @($casPort) } else { @(45783,45782) }
foreach ($port in $ports) {
  try { Invoke-RestMethod -Uri "http://127.0.0.1:$port/webhook" -Method Post -ContentType 'application/json; charset=utf-8' -Body ([Text.Encoding]::UTF8.GetBytes($body)) -TimeoutSec 2 | Out-Null; break } catch {}
}
exit 0
